using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "UnitsMiscData", menuName = "Data/Battle/Units/UnitsMiscDataCorruptedSothis")]
public class UnitsMiscDataCorruptedSothis : UnitsMiscData
{
	[Header("Corrupted Sothis")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private EvilSoulHeat evilSoulHeat;

	public override void OnEndOfAllTurns()
	{
		if (evilSoulHeat.EvilSoulHeatCounter == evilSoulHeat.EvilSoulHeatMaxCounter)
		{
			evilSoulHeat.ResetSoulHeat();
		}
	}

	public override void CustomOnPurifyEffects()
	{
		if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurn)
		{
			evilSoulHeat.ModifyEvilSoulHeat(1);
		}
	}
}
